async function scanBundle(input, deliver) {
  const decoder = new TextDecoder("utf-8", { fatal: true });
  let fragments = [];
  let line = 1;
  let count = 0;

  async function deliverLine(raw) {
    if (raw.endsWith("\r")) raw = raw.slice(0, -1);
    if (raw.trim() === "") return true;

    let value;
    try {
      value = JSON.parse(raw);
    } catch {
      const error = new Error(`Invalid JSON on line ${line}`);
      error.code = "BAD_LINE";
      error.line = line;
      throw error;
    }

    count++;
    return (await deliver(value, line)) !== false;
  }

  try {
    while (true) {
      const chunk = await input.read();

      if (chunk === null) {
        const tail = decoder.decode();
        if (tail.length !== 0) fragments.push(tail);

        if (fragments.length !== 0) {
          await deliverLine(fragments.join(""));
        }

        return count;
      }

      const text = decoder.decode(chunk, { stream: true });
      let start = 0;

      while (true) {
        const end = text.indexOf("\n", start);
        if (end === -1) break;

        fragments.push(text.slice(start, end));
        const raw = fragments.join("");
        fragments = [];

        if (!(await deliverLine(raw))) return count;

        line++;
        start = end + 1;
      }

      if (start < text.length) {
        fragments.push(text.slice(start));
      }
    }
  } finally {
    await input.close();
  }
}
